/// The definition [`POSTGRES`] holds, read once.
#[cfg(feature = "postgres")]
pub fn postgres_definition() -> Result<&'static orm::Definition, orm::Error> {
    static DEFINITION: std::sync::OnceLock<Result<orm::Definition, String>> =
        std::sync::OnceLock::new();
    DEFINITION
        .get_or_init(|| orm::Definition::parse(POSTGRES).map_err(|err| err.to_string()))
        .as_ref()
        .map_err(|err| orm::Error::Definition(err.clone()))
}

/// The repositories on Postgres.
#[cfg(feature = "postgres")]
pub mod postgres {
    use super::*;

    pub use orm::postgres::{deadpool_postgres, tokio_postgres};
    // The calendar read, feed and routes over the database's calendar
    // sources (D152, D188).
    pub use orm::calendar;
    use deadpool_postgres::GenericClient;

    /// The repository of `Contract` on a Postgres client.
    pub type ContractRepository<'a, C> =
        orm::postgres::Typed<'a, C, ContractRow, ContractCreate, ContractUpdate, ContractFilter, IdentityUUID>;

    /// The repository of `Filing` on a Postgres client.
    pub type FilingRepository<'a, C> =
        orm::postgres::Typed<'a, C, FilingRow, FilingCreate, FilingUpdate, FilingFilter, IdentityUUID>;

    /// The repository of `Holiday` on a Postgres client.
    pub type HolidayRepository<'a, C> =
        orm::postgres::Typed<'a, C, HolidayRow, HolidayCreate, HolidayUpdate, HolidayFilter, IdentityUUID>;

    /// The operations of the Recurrence `Filing` implements, under `recurrence` (D103), each run through the behaviors' core in the transaction the repositories were opened over: on the row whose key it takes, or on the table as a whole (D104).
    pub struct FilingRecurrenceOperations<'a, C>(FilingRepository<'a, C>);

    impl<C: GenericClient + Sync> FilingRecurrenceOperations<'_, C> {
        /// Sets the row's recurrence: an anchor the config's anchors take, with its rule and start (calendar), every and start (afterDone), or offset and every (relative), read in timeZone and moved off weekend days and holidays as adjust says. The occurrences that have not opened are planned again from it; the open and finished ones stay. The same recurrence is answered unchanged, but for a relative one whose date has moved: it is planned again from the date, and stays as it was set.
        pub async fn set_recurrence(
            &self,
            key: &IdentityUUID,
            params: &FilingRecurrenceSetRecurrenceParams,
            options: &WriteOptions,
        ) -> Result<FilingRecurrenceSetRecurrenceResult, orm::Error> {
            self.0
                .operation("recurrence", "setRecurrence", key, params, options)
                .await
        }

        /// Completes an occurrence: the one key names, or the earliest open one, else the earliest missed one. An open or missed occurrence is done; one that has not opened is the veto not_open, and a done or skipped one is answered unchanged. completedBy names the row that completed it, any row as references name one. An afterDone recurrence plans its next occurrence from now.
        pub async fn complete(
            &self,
            key: &IdentityUUID,
            params: &FilingRecurrenceCompleteParams,
            options: &WriteOptions,
        ) -> Result<FilingRecurrenceCompleteResult, orm::Error> {
            self.0
                .operation("recurrence", "complete", key, params, options)
                .await
        }

        /// Skips an occurrence that is upcoming, open or missed: it is finished, and the next is not held by it. A skipped or done one is answered unchanged.
        pub async fn skip(
            &self,
            key: &IdentityUUID,
            params: &FilingRecurrenceSkipParams,
            options: &WriteOptions,
        ) -> Result<FilingRecurrenceSkipResult, orm::Error> {
            self.0
                .operation("recurrence", "skip", key, params, options)
                .await
        }

        /// Moves one occurrence that is upcoming or open to another wall date-time, in the recurrence's zone, with its lead times; the rule and the other occurrences stay. A rule change drops a moved occurrence that has not opened, as it drops every one. A finished one is the veto occurrence_finished.
        pub async fn move_one(
            &self,
            key: &IdentityUUID,
            params: &FilingRecurrenceMoveOneParams,
            options: &WriteOptions,
        ) -> Result<FilingRecurrenceMoveOneResult, orm::Error> {
            self.0
                .operation("recurrence", "moveOne", key, params, options)
                .await
        }

        /// Lists the row's occurrences whose due lies in [from, to), in due order, every state, at most 500; with states, only those.
        pub async fn list_occurrences(
            &self,
            key: &IdentityUUID,
            params: &FilingRecurrenceListOccurrencesParams,
            options: &WriteOptions,
        ) -> Result<FilingRecurrenceListOccurrencesResult, orm::Error> {
            self.0
                .operation("recurrence", "listOccurrences", key, params, options)
                .await
        }
    }

    /// The tables of `fixture-recurrence-db` over `pool`, as a generated router serves
    /// its table operations from them (D106).
    pub fn tables(pool: deadpool_postgres::Pool) -> orm::postgres::Tables {
        orm::postgres::Tables::new(pool, postgres_definition)
    }

    /// The repositories of `fixture-recurrence-db` on a Postgres client, acting as a
    /// user or as no one.
    pub struct Repositories<'a, C>(orm::postgres::Repositories<'a, C>);

    impl<'a, C: GenericClient + Sync> Repositories<'a, C> {
        /// The repositories over `client`, the caller's: a connection of
        /// its pool, or a transaction on one. They act as no one until
        /// `acting` names a user.
        pub fn new(client: &'a C) -> Result<Self, orm::Error> {
            orm::postgres::Repositories::new(client, postgres_definition()?).map(Self)
        }

        /// The repositories acting as `user` (D87); `None` acts as no one.
        #[must_use]
        pub fn acting(self, user: Option<String>) -> Self {
            Self(self.0.acting(user))
        }

        /// The repositories acting as the database's system actor (D87).
        #[must_use]
        pub fn as_system(self) -> Self {
            Self(self.0.as_system())
        }

        /// The repositories with the keys of the database's `Encrypted<T>`
        /// fields (D85).
        #[must_use]
        pub fn with_keys(self, keys: &'a dyn orm::FieldKeys) -> Self {
            Self(self.0.with_keys(keys))
        }

        /// The repositories with what runs the behaviors of the tables that
        /// compose them (D103).
        #[must_use]
        pub fn with_rules(self, rules: &'a dyn orm::postgres::Rules<C>) -> Self {
            Self(self.0.with_rules(rules))
        }

        /// The repositories running each behavior's command as `caller`,
        /// whose permissions the core's guards read (D103); the acting
        /// user, holding none, unless set.
        #[must_use]
        pub fn with_caller(self, caller: orm::Caller) -> Self {
            Self(self.0.with_caller(caller))
        }

        /// The repositories keeping every read and write to what `caller`
        /// sees (D156): `orm::AccessCaller::of(ctx.principal.as_ref())` in an
        /// implementation of an operation.
        #[must_use]
        pub fn with_access(self, caller: orm::AccessCaller) -> Self {
            Self(self.0.with_access(caller))
        }

        /// The repositories telling `trace` each statement's text as it
        /// runs.
        #[must_use]
        pub fn with_trace(self, trace: &'a (dyn Fn(&str) + Sync)) -> Self {
            Self(self.0.with_trace(trace))
        }

        /// The runtime's repositories these are, over JSON objects.
        pub fn untyped(&self) -> &orm::postgres::Repositories<'a, C> {
            &self.0
        }

        /// The repository of `Contract`.
        pub fn contract(&self) -> Result<ContractRepository<'_, C>, orm::Error> {
            self.0.typed("Contract")
        }

        /// The repository of `Filing`.
        pub fn filing(&self) -> Result<FilingRepository<'_, C>, orm::Error> {
            self.0.typed("Filing")
        }

        /// The operations of `Filing`'s `recurrence`, a typed method
        /// each ([`FilingRecurrenceOperations`]).
        pub fn filing_recurrence(&self) -> Result<FilingRecurrenceOperations<'_, C>, orm::Error> {
            self.filing().map(FilingRecurrenceOperations)
        }

        /// The repository of `Holiday`.
        pub fn holiday(&self) -> Result<HolidayRepository<'_, C>, orm::Error> {
            self.0.typed("Holiday")
        }
    }
}

